"""Write the appendix tables on restoration."""

from __future__ import annotations

import argparse
import math
import sys
from pathlib import Path
from typing import Any, cast

import numpy as np
import pandas as pd
from scipy import stats

ROOT = Path(__file__).resolve().parents[2]
SUMMARY_ROOT = ROOT / "extra/output/missing_data/summary/val"
RESULTS = ROOT / "extra/output/paper/experiments/results"
HEADER = (
    "% Generated by scripts/analysis/restoration_tables.py.\n"
    "% Regenerate rather than editing by hand.\n"
)

SYNTHETIC = frozenset({"cube", "cube_nm", "cube_nonuniform_costs"})
MECHANISMS = {
    "mcar": "MCAR",
    "mar": "MAR",
    "mnar_logistic": "MNAR (Logistic)",
    "mnar_self": "MNAR (Self-Masking)",
}
METHODS = {
    "ol_full_state": r"\OL{} $(s,m)$",
    "jafa_full_state": r"\JAFA{} $(s,m)$",
    "aaco": r"\AACO{}",
    "gdfs": r"\GDFS{}",
    "jafa": r"\JAFA{} $(s)$",
    "ol_with_mask": r"\OL{} $(s)$",
    "odin_model_free": r"\ODIN{} $(s)$",
    "odin_model_free_full_state": r"\ODIN{} $(s,m)$",
    "dime": r"\DIME{}",
}
VARIANT_PAIRS = {
    r"\JAFA{}": ("jafa", "jafa_full_state"),
    r"\OL{}": ("ol_with_mask", "ol_full_state"),
    r"\ODIN{}": ("odin_model_free", "odin_model_free_full_state"),
}
APPROACHES = {
    "zero_fill": "Zero-Fill",
    "mean_fill": "Mean-Fill",
    "knn_fill": "kNN",
    "mice_fill": "MICE",
    "mice_label_fill": "MICE, Label-Conditioned",
    "pvae_label_free": "PVAE, Label-Free",
    "pvae_label_conditioned": "PVAE, Label-Conditioned",
    "pvae_multi_draw": "PVAE, Five Samples",
    "pvae_oracle": "PVAE Fit on Complete Data",
    "true_completion": "Complete Data",
}
DAMAGE_THRESHOLD = 0.01
REFERENCE_RATE = {0.3: 0.5, 0.5: 0.7, 0.7: 0.5}
ALPHA = 0.05
RATE = "0.7"
RATE_P = 0.7


def _metric(dataset: str) -> str:
    return "accuracy" if dataset in SYNTHETIC else "f_score"


def _largest_budget(frame: pd.DataFrame) -> pd.DataFrame:
    largest = frame.groupby("dataset")["eval_hard_budget"].transform("max")
    return cast("pd.DataFrame", frame[frame["eval_hard_budget"] == largest])


def _scores(paths: list[Path]) -> pd.DataFrame:
    frames = []
    for path in paths:
        frame = _largest_budget(pd.read_csv(path))
        frame = frame.assign(
            score=[
                row[f"{_metric(str(row['dataset']))}_mean"]
                for _, row in frame.iterrows()
            ]
        )
        frames.append(
            frame[["dataset", "method", "mechanism", "p", "strategy", "score"]]
        )
    merged = pd.concat(frames).astype({"p": float})
    return merged.drop_duplicates(
        ["dataset", "method", "mechanism", "p", "strategy"], keep="first"
    )


def _instances(path: Path) -> pd.DataFrame:
    frame = _largest_budget(pd.read_csv(path))
    frame = frame.assign(
        score=[
            row[_metric(str(row["dataset"]))] for _, row in frame.iterrows()
        ]
    )
    return frame.astype({"p": float})


def _cell(
    scores: pd.DataFrame, dataset: str, method: str, mechanism: str, p: float
) -> dict[str, float]:
    selected = scores[
        (scores["dataset"] == dataset)
        & (scores["method"] == method)
        & (scores["mechanism"] == mechanism)
        & (scores["p"] == p)
    ]
    return dict(
        zip(selected["strategy"], selected["score"].astype(float), strict=True)
    )


def _complete(scores: pd.DataFrame, dataset: str, method: str) -> float:
    selected = scores[
        (scores["dataset"] == dataset)
        & (scores["method"] == method)
        & (scores["strategy"] == "complete")
    ]
    return float(selected["score"].mean()) if len(selected) else math.nan


def _fmt(value: float, digits: int = 2) -> str:
    return f"${value:.{digits}f}$" if np.isfinite(value) else "--"


def _write(name: str, body: str) -> None:
    path = RESULTS / name
    path.write_text(HEADER + body)
    print(f"wrote {path}")


GROUP_NAMES = ("core_group", "induced_nonuniform", "induced_real")
PREDICTORS = ("complete", "incomplete", "restored")
INCOMPLETE_PLANNED = frozenset(
    {
        "zero_fill",
        "mean_fill",
        "knn_fill",
        "mice_fill",
        "mice_label_fill",
        "pvae_label_conditioned",
    }
)
TBD = "TBD"


def _combinations(
    scores: pd.DataFrame, members: frozenset[str], mechanism: str = "mcar"
) -> list[tuple[str, str]]:
    return [
        (dataset, method)
        for dataset in sorted(members)
        for method in METHODS
        if "restricted" in _cell(scores, dataset, method, mechanism, RATE_P)
    ]


def _recovered(
    scores: pd.DataFrame,
    trained: pd.DataFrame,
    combinations: list[tuple[str, str]],
    strategy: str,
    mechanism: str = "mcar",
) -> float | None:
    gain = damage = 0.0
    for dataset, method in combinations:
        cell = _cell(trained, dataset, method, mechanism, RATE_P)
        if "restricted" not in cell or strategy not in cell:
            return None
        complete = _complete(scores, dataset, method)
        gain += cell[strategy] - cell["restricted"]
        damage += complete - cell["restricted"]
    return gain / damage if damage else None


def _mean_damage(
    scores: pd.DataFrame,
    trained: pd.DataFrame,
    combinations: list[tuple[str, str]],
) -> float | None:
    damages = []
    for dataset, method in combinations:
        cell = _cell(trained, dataset, method, "mcar", RATE_P)
        if "restricted" not in cell:
            return None
        damages.append(_complete(scores, dataset, method) - cell["restricted"])
    return float(np.mean(damages)) if damages else None


def _entry(value: float | None, digits: int = 2) -> str:
    return TBD if value is None else _fmt(value, digits)


def _quality(path: Path) -> pd.DataFrame | None:
    if not path.exists():
        return None
    frame = pd.read_csv(path)
    return frame


def _restored_score(
    quality: pd.DataFrame | None, strategy: str, members: frozenset[str]
) -> str:
    metric = "accuracy" if members <= SYNTHETIC else "f_score"
    if quality is None or f"restored_{metric}" not in quality:
        return TBD
    rows = quality[
        quality["dataset"].isin(list(members)) & (quality["split"] == "val")
    ]
    if strategy == "true_completion":
        return _fmt(float(rows[f"complete_{metric}"].mean()), 3)
    rows = rows[rows["strategy"] == strategy]
    value = float(rows[f"restored_{metric}"].mean())
    return _fmt(value, 3) if np.isfinite(value) else TBD


def _rmse(
    quality: pd.DataFrame | None, strategy: str, members: frozenset[str]
) -> str:
    if quality is None or strategy == "true_completion":
        return "--"
    rows = quality[
        quality["dataset"].isin(list(members))
        & (quality["strategy"] == strategy)
        & (quality["split"] == "train")
    ]
    return _fmt(float(rows["rmse"].mean()), 2) if len(rows) else TBD


REFERENCES = frozenset({"pvae_oracle", "true_completion"})


def _highlight(rows: list[list[str]], lower: list[bool]) -> None:
    """Bold the best and underline the second best entry of each column."""
    for column, low in enumerate(lower, start=1):
        if any(row[column] == TBD for row in rows):
            continue
        values = []
        for index, row in enumerate(rows):
            try:
                values.append((float(row[column].strip("$")), index))
            except ValueError:
                continue
        ranked = sorted({v for v, _ in values}, reverse=not low)
        for value, index in values:
            number = rows[index][column].strip("$")
            if value == ranked[0]:
                rows[index][column] = rf"$\mathbf{{{number}}}$"
            elif len(ranked) > 1 and value == ranked[1]:
                rows[index][column] = rf"\underline{{${number}$}}"


def approaches_table(
    scores: pd.DataFrame,
    trained: dict[str, pd.DataFrame],
    quality: pd.DataFrame | None,
) -> None:
    datasets = frozenset(scores["dataset"].unique())
    groups = (SYNTHETIC & datasets, datasets - SYNTHETIC)
    combinations = [_combinations(scores, members) for members in groups]
    for members, selected in zip(groups, combinations, strict=True):
        print(f"restoration approaches: {sorted(members)}: {len(selected)}")
    sizes = f"${len(combinations[0])}$ synthetic and ${len(combinations[1])}$"

    def recovered(strategy: str, predictor: str) -> list[str]:
        if strategy == "true_completion":
            return ["$1.00$"] * 2
        return [
            _entry(_recovered(scores, trained[predictor], c, strategy))
            for c in combinations
        ]

    ranked: list[list[str]] = []
    references: list[list[str]] = []
    for strategy, label in APPROACHES.items():
        cells = [label]
        cells += [_rmse(quality, strategy, m) for m in groups]
        cells += [_restored_score(quality, strategy, m) for m in groups]
        cells += recovered(strategy, "complete")
        (references if strategy in REFERENCES else ranked).append(cells)
    _highlight(ranked, [True, True, False, False, False, False])
    rows = [" & ".join(c) + r" \\" for c in ranked]
    rows += [r"\midrule"] + [" & ".join(c) + r" \\" for c in references]
    _write(
        "restoration_approaches.tex",
        r"""\begin{table}[H]
\centering
\caption{Properties of each imputation, averaged over the datasets: RMSE on the missing training values, and accuracy (synthetic) and macro-F1 (real-world) of the complete-data predictor on the restored validation data with all features observed. Resulting AFA performance: fraction of the missingness damage recovered under MCAR at $p = 0.7$, pooled over the """
        + sizes
        + r""" real-world method--dataset combinations.}
\label{tab:restoration-approaches}
{\footnotesize
\begin{tabular}{lcccccc}
\toprule
& \multicolumn{2}{c}{RMSE ($\downarrow$)} & \multicolumn{2}{c}{Accuracy / F1 ($\uparrow$)} & \multicolumn{2}{c}{Recovered ($\uparrow$)} \\
\cmidrule(lr){2-3} \cmidrule(lr){4-5} \cmidrule(lr){6-7}
Restoration & Syn. & Real & Syn. & Real & Syn. & Real \\
\midrule
"""
        + "\n".join(rows)
        + r"""
\bottomrule
\end{tabular}
}
\end{table}
""",
    )
    damage = [r"\emph{Damage}"]
    for predictor in PREDICTORS:
        damage += [
            _entry(_mean_damage(scores, trained[predictor], selected), 3)
            for selected in combinations
        ]
    ranked = []
    for strategy, label in APPROACHES.items():
        if strategy not in INCOMPLETE_PLANNED:
            continue
        cells = [label]
        for predictor in PREDICTORS:
            cells += recovered(strategy, predictor)
        ranked.append(cells)
    _highlight(ranked, [False] * 6)
    rows = [" & ".join(damage) + r" \\", r"\midrule"]
    rows += [" & ".join(c) + r" \\" for c in ranked]
    _write(
        "predictor_ablation.tex",
        r"""\begin{table}[H]
\centering
\caption{Mean missingness damage and fraction of the damage recovered under MCAR at $p = 0.7$ with the predictor trained on complete data, on the incomplete training data, or on the restored training data of each approach, over the same """
        + sizes
        + r""" real-world method--dataset combinations as \Cref{tab:restoration-approaches}.}
\label{tab:predictor-ablation}
{\footnotesize
\begin{tabular}{lcccccc}
\toprule
& \multicolumn{6}{c}{Predictor Trained on} \\
\cmidrule(lr){2-7}
& \multicolumn{2}{c}{Complete Data} & \multicolumn{2}{c}{Incomplete Data} & \multicolumn{2}{c}{Restored Data} \\
\cmidrule(lr){2-3} \cmidrule(lr){4-5} \cmidrule(lr){6-7}
Restoration & Syn. & Real & Syn. & Real & Syn. & Real \\
\midrule
"""
        + "\n".join(rows)
        + r"""
\bottomrule
\end{tabular}
}
\end{table}
""",
    )


GROUPS = (
    (-math.inf, 0.01, "$< 0.01$"),
    (0.01, 0.05, "$0.01$--$0.05$"),
    (0.05, math.inf, r"$\geq 0.05$"),
)


def _significance(
    instances: pd.DataFrame,
    dataset: str,
    method: str,
    mechanism: str = "mcar",
    strategy: str = "pvae_label_conditioned",
) -> int | None:
    selected = instances[
        (instances["dataset"] == dataset)
        & (instances["method"] == method)
        & (instances["mechanism"] == mechanism)
        & (instances["p"] == RATE_P)
    ]
    pivot = selected.pivot_table(
        index="instance", columns="strategy", values="score"
    )
    if not {"restricted", strategy} <= set(pivot.columns):
        return None
    difference = (pivot[strategy] - pivot["restricted"]).dropna()
    if float(difference.std()) == 0.0:
        pvalue = 0.0 if float(difference.mean()) != 0.0 else 1.0
    else:
        pvalue = float(cast("Any", stats.ttest_1samp(difference, 0.0)).pvalue)
    if pvalue >= ALPHA:
        return 0
    return 1 if difference.mean() > 0 else -1


def damage_groups_table(
    scores: pd.DataFrame, paper: pd.DataFrame, instances: pd.DataFrame
) -> None:
    rows = []
    totals = [0, 0, 0]
    for low, high, label in GROUPS:
        selected = []
        for dataset in sorted(scores["dataset"].unique()):
            for method in METHODS:
                cell = _cell(scores, dataset, method, "mcar", RATE_P)
                reference = _cell(
                    paper, dataset, method, "mcar", REFERENCE_RATE[RATE_P]
                )
                complete = _complete(scores, dataset, method)
                needed = {"restricted", "pvae_label_conditioned"}
                if not needed <= set(cell) or "restricted" not in reference:
                    continue
                if low <= complete - reference["restricted"] < high:
                    selected.append((dataset, method, cell, complete))
        synthetic = sum(dataset in SYNTHETIC for dataset, *_ in selected)
        damage = np.mean([c - cell["restricted"] for *_, cell, c in selected])
        gains = [
            _fmt(
                float(
                    np.mean(
                        [
                            cell[strategy] - cell["restricted"]
                            for *_, cell, _ in selected
                            if strategy in cell
                        ]
                    )
                ),
                3,
            )
            for strategy in ("pvae_label_conditioned", "mice_label_fill")
        ]
        signs = [_significance(instances, d, m) for d, m, *_ in selected]
        counts = [signs.count(1), signs.count(-1)]
        totals = [
            totals[0] + counts[0],
            totals[1] + counts[1],
            totals[2] + len(selected),
        ]
        rows.append(
            f"{label} & ${synthetic}$ / ${len(selected) - synthetic}$ & "
            f"{_fmt(float(damage), 3)} & "
            + " & ".join(gains)
            + f" & ${counts[0]}$ & ${counts[1]}$"
            + r" \\"
        )
    print(f"damage groups: better, worse, total: {totals}")
    _write(
        "damage_groups.tex",
        r"""\begin{table}[H]
\centering
\caption{Mean gain of restoration over restricted training under MCAR at $p = 0.7$, with method--dataset combinations grouped by their missingness damage on the runs at $p = 0.5$, and number of combinations where the PVAE is significantly better or worse than restricted training (paired $t$-test over five splits, $\alpha = 0.05$, uncorrected).}
\label{tab:damage-groups}
{\footnotesize
\setlength{\tabcolsep}{4pt}
\begin{tabular}{lcccccc}
\toprule
& & & \multicolumn{2}{c}{Mean Gain} & \multicolumn{2}{c}{PVAE} \\
\cmidrule(lr){4-5} \cmidrule(lr){6-7}
Damage at $p = 0.5$ & Syn. / Real & Mean Damage & PVAE & MICE, Label-Conditioned & Better & Worse \\
\midrule
"""
        + "\n".join(rows)
        + r"""
\bottomrule
\end{tabular}
}
\end{table}
""",
    )


def mechanism_table(scores: pd.DataFrame, instances: pd.DataFrame) -> None:
    datasets = frozenset(scores["dataset"].unique())
    rows = []
    for mechanism, label in MECHANISMS.items():
        selected = _combinations(scores, datasets, mechanism)
        signs = [
            _significance(instances, d, m, mechanism) for d, m in selected
        ]
        selected = [
            c for c, s in zip(selected, signs, strict=True) if s is not None
        ]
        signs = [s for s in signs if s is not None]
        recovered = [
            _recovered(scores, scores, selected, strategy, mechanism)
            for strategy in ("pvae_label_conditioned", "mice_label_fill")
        ]
        rows.append(
            f"{label} & "
            + " & ".join(_fmt(v) if v is not None else "--" for v in recovered)
            + " & "
            + " & ".join(f"${signs.count(v)}$" for v in (1, -1, 0))
            + r" \\"
        )
    _write(
        "mechanism_recovery.tex",
        r"""\begin{table}[H]
\centering
\caption{Generative restoration against restricted training at $p = 0.7$ over all $72$ method--dataset combinations: fraction of the damage recovered, pooled over combinations, and number of combinations where the PVAE is significantly better, significantly worse, or not significantly different (paired $t$-test over five splits, $\alpha = 0.05$, uncorrected).}
\label{tab:mechanism-recovery}
{\footnotesize
\setlength{\tabcolsep}{4pt}
\begin{tabular}{lccccc}
\toprule
& \multicolumn{2}{c}{Recovered ($\uparrow$)} & \multicolumn{3}{c}{PVAE} \\
\cmidrule(lr){2-3} \cmidrule(lr){4-6}
Mechanism & PVAE & MICE, Label-Conditioned & Better & Worse & n.s. \\
\midrule
"""
        + "\n".join(rows)
        + r"""
\bottomrule
\end{tabular}
}
\end{table}
""",
    )


def size_table() -> None:
    rows = []
    for n in (500, 1000, 4000, 16000):
        path = SUMMARY_ROOT / f"size_sweep_n{n}" / "summary.csv"
        if not path.exists():
            continue
        scores = _scores([path])
        entries = []
        for dataset in ("cube", "cube_nm"):
            methods = [
                method
                for method in METHODS
                if "restricted"
                in _cell(scores, dataset, method, "mcar", float(RATE))
            ]
            cells = [
                _cell(scores, dataset, m, "mcar", float(RATE)) for m in methods
            ]
            complete = [_complete(scores, dataset, m) for m in methods]
            damage = np.mean(
                [
                    c - cell["restricted"]
                    for cell, c in zip(cells, complete, strict=True)
                ]
            )
            errors = [
                np.mean(
                    [
                        cell[strategy] - c
                        for cell, c in zip(cells, complete, strict=True)
                    ]
                )
                for strategy in ("pvae_label_conditioned", "pvae_oracle")
            ]
            entries.append(
                f"{_fmt(float(damage), 3)} & "
                + " & ".join(_fmt(float(e), 3) for e in errors)
            )
        rows.append(f"${n}$ & " + " & ".join(entries) + r" \\")
    _write(
        "size_sweep.tex",
        r"""\begin{table}[H]
\centering
\caption{Missingness damage and restoration error under MCAR at $p = 0.7$ against the dataset size $n$, averaged over methods.}
\label{tab:size-sweep}
{\footnotesize
\setlength{\tabcolsep}{3.5pt}
\begin{tabular}{lcccccc}
\toprule
& \multicolumn{3}{c}{CUBE} & \multicolumn{3}{c}{CUBE-NM} \\
\cmidrule(lr){2-4} \cmidrule(lr){5-7}
$n$ & Damage & PVAE & PVAE Fit on Complete Data & Damage & PVAE & PVAE Fit on Complete Data \\
\midrule
"""
        + "\n".join(rows)
        + r"""
\bottomrule
\end{tabular}
}
\end{table}
""",
    )


EXTRA_NAMESPACES = [
    "core_group_missingness_v2",
    "induced_real_missingness_v2",
    "induced_nonuniform_missingness_v2",
    *(
        f"{kind}_{group}"
        for kind in (
            "sklearn_imputers",
            "mice_label",
            "multi_draw",
            "constant_fill",
            "pvae_variants",
        )
        for group in GROUP_NAMES
    ),
    "mar_core_group",
    "mar_induced_nonuniform",
    "mnar_self_core_group",
    "mnar_self_induced_nonuniform",
    "mar_induced_real",
    "mnar_self_induced_real",
]


def _existing(names: list[str]) -> list[Path]:
    paths = [SUMMARY_ROOT / name / "summary.csv" for name in names]
    missing = [
        name for name, p in zip(names, paths, strict=True) if not p.exists()
    ]
    if missing:
        print(f"missing summaries: {missing}", file=sys.stderr)
    return [path for path in paths if path.exists()]


def _trained(scores: pd.DataFrame) -> dict[str, pd.DataFrame]:
    restored = _existing(
        [f"view_classifier_{g}" for g in GROUP_NAMES]
        + [f"view_classifier_extra_{g}" for g in GROUP_NAMES]
    )
    restored_scores = _scores(restored)
    restricted = cast(
        "pd.DataFrame",
        restored_scores[restored_scores["strategy"] == "restricted"],
    )
    incomplete = _existing(
        [
            f"restricted_predictor_{kind}_{g}"
            for kind in ("fills", "models")
            for g in GROUP_NAMES
        ]
    )
    frames = [restricted] + ([_scores(incomplete)] if incomplete else [])
    return {
        "complete": scores,
        "incomplete": pd.concat(frames),
        "restored": restored_scores,
    }


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--namespace", default="induced")
    arguments = parser.parse_args()
    paths = [SUMMARY_ROOT / arguments.namespace / "summary.csv"]
    paths += _existing(EXTRA_NAMESPACES)
    scores = _scores(paths)
    paper = _scores(paths[:1])
    instances = _instances(
        SUMMARY_ROOT / arguments.namespace / "instance_metrics.csv"
    )
    damage_groups_table(scores, paper, instances)
    approaches_table(
        scores,
        _trained(scores),
        _quality(SUMMARY_ROOT / "imputation_quality.csv"),
    )
    mechanism_table(scores, instances)
    size_table()


if __name__ == "__main__":
    main()
